// Pembahasan untuk SISWA, Bahasa Indonesia Lanjutan (quiz id "ind"), soal nomor 1 sampai 30.
// Dibuat dari dokumen "Soal Bahasa Indonesia Lanjutan, Soal dan Pembahasan Edisi Siswa No1-30":
// kata kunci, langkah menjawab, bukti di teks, bedah tiap pilihan jawaban (lengkap dengan jenis jebakan), dan jurus.
//
// Cara dipakai:
//  - Kunci pada EXPLAIN_SISWA adalah nomor soal.
//  - Server hanya mengirim pembahasan nomor N setelah siswa itu menjawab soal N (lihat studentExplainOf di quizzes.js),
//    jadi siswa tidak bisa mengintip pembahasan soal yang belum dijawab.
//  - Pembahasan untuk guru (login "Ferdi") tetap di questions-indonesia.js (field explain), tidak berubah.
//  - Inti teks tiap bagian dipasang di pembahasan soal terakhir bagian itu (5, 10, 15, 20, 25, 30).
//
// Untuk mengubah isi: edit teks HTML di bawah. Kelas CSS (box, ev, keystatus, trap) ada di public/style.css.

export const EXPLAIN_SISWA = {
  "1": "<p class=\"keystatus ok\"><b>Jawaban: C</b> · Jenis soal: Gagasan Utama</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>gagasan utama</b> → inti seluruh teks (payung)</li><li><b>teks tersebut</b> → semua paragraf, bukan satu detail</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Beri label tiap paragraf: rancangan → temuan sekolah → hasil + pembatas → simpulan.</li><li>Cari benang merahnya: hubungan pola tidur dengan kemampuan, dipengaruhi banyak hal.</li><li>Pilih opsi yang menaungi semuanya. Coret opsi bertanda kata mutlak (satu-satunya, seluruh, selalu, hanya).</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P3]</b> <i>“Namun, hubungan itu tidak berarti bahwa durasi tidur semata-mata menyebabkan perbedaan kemampuan.”</i><br><b>Maknanya:</b> Durasi bukan satu-satunya penentu.</p><p class=\"ev\"><b>[P4]</b> <i>“Upaya perbaikan perlu mempertimbangkan keteraturan jadwal, kualitas tidur, beban kegiatan, dan kebiasaan sebelum tidur.”</i><br><b>Maknanya:</b> Simpulan menyebut banyak faktor.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev no\"><b>A. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Kata “satu-satunya” bertentangan dengan P3.</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>“Seluruh siswa” berlebihan; gawai hanya menurunkan kualitas tidur sebagian siswa.</p>\n<p class=\"ev ok\"><b>C. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Merangkum keempat paragraf: rancangan, temuan, pembatas, simpulan.</p>\n<p class=\"ev no\"><b>D. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Teks hanya menyebut mereka cenderung tidur lebih singkat; tidak ada data “selalu lebih rendah”.</p>\n<p class=\"ev no\"><b>E. Salah</b> · <span class=\"trap\">Tidak ada di teks</span><br>Teks memakai tiga sumber data; tidak ada saran memakai satu alat saja.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Uji payung: tanya tiap opsi, “Apakah ini mewakili paragraf 1, 2, 3, dan 4?” Opsi yang hanya mewakili satu paragraf adalah ranting.</p></section>",
  "2": "<p class=\"keystatus ok\"><b>Jawaban: A</b> · Jenis soal: Implikasi • Kebijakan Sekolah</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>implikasi teks</b> → langkah logis yang mengikuti temuan</li><li><b>paling sesuai</b> → paling konsisten dengan seluruh temuan</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Rangkum temuan dalam satu kalimat: yang penting keteraturan dan kualitas, bukan sekadar lama tidur.</li><li>Ubah jadi tuntutan kebijakan: atur jadwal, batasi gawai, tinjau beban kegiatan.</li><li>Coret kebijakan yang berpegang pada satu faktor saja atau menunggu bukti mutlak.</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P4]</b> <i>“Kebijakan sekolah yang hanya menganjurkan siswa tidur lebih lama belum memadai.”</i><br><b>Maknanya:</b> Tidur lebih lama saja belum cukup.</p><p class=\"ev\"><b>[P4]</b> <i>“Upaya perbaikan perlu mempertimbangkan keteraturan jadwal, kualitas tidur, beban kegiatan, dan kebiasaan sebelum tidur.”</i><br><b>Maknanya:</b> Empat hal harus ikut ditimbang.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev ok\"><b>A. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Persis simpulan P4: keteraturan, kebiasaan sebelum tidur, beban kegiatan.</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Anjuran tidur lebih lama saja dinilai belum memadai.</p>\n<p class=\"ev no\"><b>C. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Belajar malam hanya satu faktor; tidak ada bukti “satu-satunya penyebab”.</p>\n<p class=\"ev no\"><b>D. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Teks menegaskan tidur lebih lama belum tentu berkualitas bila sering terputus atau tidak teratur.</p>\n<p class=\"ev no\"><b>E. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Penelitian lanjutan memang perlu, tetapi teks tidak menyuruh menunda semua kebijakan.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Rumus Temuan → Tuntutan → Kebijakan. Opsi yang tidak bisa dihubungkan ke temuan mana pun otomatis gugur.</p></section>",
  "3": "<p class=\"keystatus ok\"><b>Jawaban: A · C · D</b> · Jenis soal: Evaluasi · Pilih semua</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>dapat dipertanggungjawabkan</b> → ada dasar di teks dan tidak melebihi bukti</li><li><b>pilih semua</b> → periksa tiap opsi satu per satu</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Siapkan tiga “kacamata”: rancangan (apa yang dicatat), temuan (hasilnya), keterbatasan (yang belum pasti).</li><li>Uji tiap opsi: apakah klaimnya melampaui bukti? Kata “pasti” dan “cukup untuk memastikan” adalah lampu merah.</li><li>Pilih semua opsi yang lolos uji.</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P2]</b> <i>“Untuk mengurangi kesalahan penafsiran, peneliti juga mencatat konsumsi kafein, beban tugas, dan kondisi ruang tidur.”</i><br><b>Maknanya:</b> Faktor lain dicatat agar hasil tidak ditafsirkan terlalu sederhana.</p><p class=\"ev\"><b>[P4]</b> <i>“Penelitian lanjutan dengan pengamatan lebih panjang juga diperlukan”</i><br><b>Maknanya:</b> Penelitian ini belum cukup untuk memastikan sebab-akibat.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev ok\"><b>A. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Sesuai P2: faktor lain dicatat “untuk mengurangi kesalahan penafsiran”.</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Loncatan logika: yang berhubungan dengan skor adalah keteraturan, bukan sekadar durasi. Kata “pasti” berlebihan.</p>\n<p class=\"ev ok\"><b>C. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Ada tiga sumber data, tetapi P4 mengakui kebiasaan belajar dan kondisi keluarga belum bisa dibedakan.</p>\n<p class=\"ev ok\"><b>D. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Sesuai P3: durasi sedikit pendek, tetapi jadwal konsisten dan gawai terbatas, kinerja tetap baik.</p>\n<p class=\"ev no\"><b>E. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Teks justru meminta penelitian lanjutan dengan pengamatan lebih panjang.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Bedakan “membantu/menunjukkan” dari “membuktikan/memastikan”. Evaluasi penelitian yang kuat biasanya memakai kata pertama.</p></section>",
  "4": "<p class=\"keystatus ok\"><b>Jawaban: E</b> · Jenis soal: Sebab • Alasan Peneliti</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>mengapa</b> → cari alasan (kata “karena” atau “untuk”)</li><li><b>selain mengukur pola tidur</b> → faktor tambahan</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Loncat ke P2, tempat faktor tambahan disebut.</li><li>Cari kata penanda alasan: “karena dapat memengaruhi ...”.</li><li>Cocokkan dengan opsi yang memuat alasan itu, bukan tujuan lain.</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P2]</b> <i>“Faktor-faktor tersebut dipertimbangkan karena dapat memengaruhi kebugaran dan konsentrasi secara bersamaan.”</i><br><b>Maknanya:</b> Faktor tambahan ikut memengaruhi hasil, jadi harus dihitung.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev no\"><b>A. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Teks justru menyebut jadwal dan kondisi tiap sekolah berbeda; tidak ada upaya menyamakan.</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Kafein hanya satu faktor yang dicatat; tidak ada simpulan kafein sebagai penyebab utama.</p>\n<p class=\"ev no\"><b>C. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Tiga sumber data dipakai bersamaan; tidak ada yang menggantikan yang lain.</p>\n<p class=\"ev no\"><b>D. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Simpulan teks sebaliknya: keteraturan dan kualitas ikut menentukan.</p>\n<p class=\"ev ok\"><b>E. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Sama dengan alasan di P2: faktor lain memengaruhi kebugaran dan konsentrasi.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Kenali kata penanda alasan: karena, sebab, untuk, agar, sehingga. Untuk soal “mengapa”, lingkari kata-kata itu di paragraf yang dituju.</p></section>",
  "5": "<p class=\"keystatus ok\"><b>Jawaban: B</b> · Jenis soal: Implikasi • Kebijakan Sekolah</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>hasil dan keterbatasan</b> → temuan + hal yang belum pasti</li><li><b>paling sesuai dengan simpulan</b> → sejalan dengan kesimpulan peneliti</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Ingat simpulan P4: keteraturan, kualitas, beban kegiatan, kebiasaan sebelum tidur.</li><li>Cari opsi yang memuat tiga unsur: jadwal teratur, batasi gawai, tinjau beban kegiatan.</li><li>Coret opsi yang memaksakan satu solusi untuk semua.</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P3]</b> <i>“Siswa yang tidur cukup tetapi menghadapi beban tugas berat tetap dapat mengalami penurunan konsentrasi.”</i><br><b>Maknanya:</b> Tidur cukup belum menjamin konsentrasi baik.</p><p class=\"ev\"><b>[P4]</b> <i>“Upaya perbaikan perlu mempertimbangkan keteraturan jadwal, kualitas tidur, beban kegiatan, dan kebiasaan sebelum tidur.”</i><br><b>Maknanya:</b> Dasar kebijakan yang tepat.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev no\"><b>A. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Persis kebijakan yang dinilai peneliti belum memadai.</p>\n<p class=\"ev ok\"><b>B. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Memuat tiga unsur simpulan peneliti.</p>\n<p class=\"ev no\"><b>C. Salah</b> · <span class=\"trap\">Setengah benar</span><br>Beban kegiatan memang perlu ditinjau, tetapi membatasi pada rata-rata durasi mengabaikan keteraturan, kualitas, dan gawai.</p>\n<p class=\"ev no\"><b>D. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>P3: tidur cukup tetapi beban tugas berat tetap dapat menurunkan konsentrasi. Kata “pasti” berlebihan.</p>\n<p class=\"ev no\"><b>E. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Kualitas tidur dinilai dari catatan harian, perangkat pemantau, dan wawancara. Tes mengukur kemampuan, bukan kualitas tidur.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Bandingkan jawaban benar soal 2 (A) dan soal 5 (B): tiga unsurnya sama, hanya kalimatnya diparafrasekan.</p></section>\n<section class=\"box catatan\"><h4>Inti teks (rangkuman bagian 1)</h4><p>Penelitian 8 minggu di 4 SMA: tidur yang teratur dan jarang terputus berhubungan dengan skor pemecahan masalah yang lebih tinggi. Namun, durasi tidur bukan satu-satunya penyebab, sehingga kebijakan tidak boleh hanya menyuruh tidur lebih lama.</p></section>",
  "6": "<p class=\"keystatus ok\"><b>Jawaban: A · C · E</b> · Jenis soal: Evaluasi • Tindakan Sesuai Prinsip Maya · Pilih semua</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>tindakan evaluatif</b> → langkah menilai hasil uji coba</li><li><b>prinsip Maya</b> → pertimbangan di P2–P3</li><li><b>pilih semua</b> → periksa tiap opsi</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Tulis dulu prinsip Maya: (1) pemeriksaan petugas tetap ada, (2) tidak menilai hanya dari kecepatan, (3) keluhan tidak langsung dianggap akibat sistem, (4) uji kestabilan di periode puncak, (5) cek kualitas data dan beban kerja.</li><li>Cocokkan tiap opsi: menjalankan atau melanggar salah satu prinsip?</li><li>Coret yang bertentangan (B dan D), tandai semua yang lolos.</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P2]</b> <i>“Maya tidak mengusulkan penghapusan pemeriksaan petugas.”</i><br><b>Maknanya:</b> Prinsip 1.</p><p class=\"ev\"><b>[P2]</b> <i>“Ia juga meminta agar keberhasilan tidak dinilai hanya dari kecepatan menemukan barang.”</i><br><b>Maknanya:</b> Prinsip 2.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev ok\"><b>A. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Sejalan dengan niat Maya menguji kestabilan sebelum memperluas sistem.</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Maya tidak ingin menghapus pemeriksaan petugas. Kata “satu-satunya” berlebihan.</p>\n<p class=\"ev ok\"><b>C. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Maya menilai ketiga perubahan sekaligus dan menolak penilaian hanya dari kecepatan.</p>\n<p class=\"ev no\"><b>D. Salah</b> · <span class=\"trap\">Setengah benar</span><br>Faktanya benar (13 poin &lt; 33 poin), tetapi “gagal” tidak mengikuti: keluhan punya faktor lain dan indeksnya tetap turun.</p>\n<p class=\"ev ok\"><b>E. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Sesuai P2 dan P3 tentang kualitas data, beban kerja, dan pemeriksaan keselamatan.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Pada soal “sesuai prinsip tokoh”, tulis dulu prinsipnya, baru uji opsi satu per satu.</p></section>",
  "7": "<p class=\"keystatus ok\"><b>Jawaban: D</b> · Jenis soal: Rumusan • Prinsip Evaluasi</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>merumuskan prinsip</b> → menyimpulkan pola pikir tokoh</li><li><b>paling tepat</b> → paling lengkap dan paling sesuai teks</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Ingat lima pertimbangan Maya (lihat soal 6).</li><li>Opsi yang berpegang pada satu indikator saja pasti kurang lengkap.</li><li>Pilih opsi yang menyatukan beberapa indikator dengan kehati-hatian sebelum meluas.</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P2]</b> <i>“Ia juga meminta agar keberhasilan tidak dinilai hanya dari kecepatan menemukan barang.”</i><br><b>Maknanya:</b> Penilaian harus lebih dari satu indikator.</p><p class=\"ev\"><b>[P3]</b> <i>“penurunan keluhan tidak boleh langsung dianggap sepenuhnya akibat sistem gudang”</i><br><b>Maknanya:</b> Hasil perlu ditafsirkan hati-hati.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev no\"><b>A. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Maya justru meminta keberhasilan tidak dinilai hanya dari kecepatan.</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>“Sudah cukup” berlebihan; kestabilan, mutu data, dan beban kerja masih harus diuji.</p>\n<p class=\"ev no\"><b>C. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Maya menegaskan keluhan tidak boleh langsung dianggap akibat sistem karena ada faktor lain.</p>\n<p class=\"ev ok\"><b>D. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Merangkum seluruh pertimbangan Maya di P2 dan P3.</p>\n<p class=\"ev no\"><b>E. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Hasil baru dari satu zona dan belum diuji pada periode pesanan tertinggi.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Opsi “paling lengkap” sering terasa paling panjang, tetapi panjang bukan jaminan benar. Periksa apakah tiap bagian opsi punya bukti di teks.</p></section>",
  "8": "<p class=\"keystatus ok\"><b>Jawaban: B</b> · Jenis soal: Sebab • Alasan Maya</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>penurunan keluhan</b> → indeks 60</li><li><b>belum dianggap akibat sistem</b> → ada faktor lain yang ikut berperan</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Loncat ke P3.</li><li>Baca kalimat setelah “tidak boleh langsung dianggap ...”.</li><li>Cocokkan dengan opsi yang menyebut faktor lain: informasi ke bengkel, kendaraan pengangkut, mutu kemasan.</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P3]</b> <i>“Keluhan dapat dipengaruhi ketepatan informasi kepada bengkel, keterlambatan kendaraan pengangkut, atau mutu kemasan.”</i><br><b>Maknanya:</b> Tiga faktor di luar sistem gudang.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev no\"><b>A. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Faktanya indeks keluhan turun (60 → 47), bukan naik.</p>\n<p class=\"ev ok\"><b>B. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Hampir sama dengan kalimat di P3.</p>\n<p class=\"ev no\"><b>C. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Sistem menampilkan status pesanan lewat dasbor, dan kesalahan pengiriman turun.</p>\n<p class=\"ev no\"><b>D. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Tidak ada aturan seperti itu di teks. Kata “selalu” berlebihan.</p>\n<p class=\"ev no\"><b>E. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Ketiga indeks dibaca bersama dalam satu diagram.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Buat peta sebab keluhan: gudang, informasi ke bengkel, kendaraan, kemasan. Gudang hanya satu dari empat sebab, jadi hasilnya tidak bisa diklaim sepenuhnya milik sistem.</p></section>",
  "9": "<p class=\"keystatus ok\"><b>Jawaban: D</b> · Jenis soal: Evaluasi • Rencana Perluasan</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>evaluasi rencana memperluas</b> → menimbang layak atau tidaknya</li><li><b>setelah uji coba</b> → berdasarkan hasil uji</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Isi “neraca”: apa hasil awalnya (+), apa yang masih harus diuji (−).</li><li>Cari opsi yang memuat kedua sisi.</li><li>Coret opsi “langsung layak”, “hentikan”, atau “belum bisa dinilai sama sekali”.</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P3]</b> <i>“Maya menilai ketiga perubahan itu menjanjikan”</i><br><b>Maknanya:</b> Hasil awal baik (sisi +).</p><p class=\"ev\"><b>[P3]</b> <i>“Sebelum memperluas sistem, ia ingin menguji kestabilan hasil pada periode pesanan tertinggi”</i><br><b>Maknanya:</b> Masih ada syarat (sisi −).</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev no\"><b>A. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Hasil baru dari satu zona; periode puncak belum diuji.</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Keluhan tetap turun; penurunan kecil bukan alasan menghentikan, justru perlu menelusuri faktor lain.</p>\n<p class=\"ev no\"><b>C. Salah</b> · <span class=\"trap\">Setengah benar</span><br>Maya menegaskan keberhasilan tidak hanya dari kecepatan; mutu data dan beban kerja juga dinilai.</p>\n<p class=\"ev ok\"><b>D. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Seimbang: ada pencapaian dan ada syarat.</p>\n<p class=\"ev no\"><b>E. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Indeks relatif tetap bisa dipakai membandingkan sebelum dan sesudah. Menolak data sepenuhnya berlebihan.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Evaluasi yang baik seimbang: mengakui hasil awal dan menyebut syarat. Tanya diri sendiri, “Opsi mana yang hanya mengisi satu sisi timbangan?”</p></section>",
  "10": "<p class=\"keystatus ok\"><b>Jawaban: A · C · E</b> · Jenis soal: Evaluasi • Tindakan Sesuai Pertimbangan · Pilih semua</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>sesuai pertimbangan Maya</b> → konsisten dengan prinsipnya</li><li><b>pilih semua yang tepat</b> → periksa tiap opsi</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Ingat lima prinsip Maya (lihat soal 6).</li><li>Coret opsi yang menghapus pemeriksaan petugas atau menyatakan “sepenuhnya berhasil”.</li><li>Tandai opsi yang menjalankan prinsip.</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P3]</b> <i>“Keluhan dapat dipengaruhi ketepatan informasi kepada bengkel, keterlambatan kendaraan pengangkut, atau mutu kemasan.”</i><br><b>Maknanya:</b> Dasar untuk opsi C.</p><p class=\"ev\"><b>[P3]</b> <i>“menilai apakah prosedur baru menambah beban kerja tanpa mengurangi pemeriksaan keselamatan”</i><br><b>Maknanya:</b> Dasar untuk opsi E.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev ok\"><b>A. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Maya ingin menguji kestabilan hasil sebelum memperluas sistem.</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Maya tidak ingin menghapus pemeriksaan petugas.</p>\n<p class=\"ev ok\"><b>C. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Keluhan dipengaruhi informasi, kendaraan, dan kemasan, jadi harus dibaca bersama indikator lain.</p>\n<p class=\"ev no\"><b>D. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>“Sepenuhnya berhasil” bertentangan dengan kehati-hatian Maya.</p>\n<p class=\"ev ok\"><b>E. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Sesuai P3 tentang kualitas data, beban kerja, dan keselamatan.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Soal 6 dan 10 punya opsi benar yang hampir sama (A, C, E). Soal berbeda bisa menguji logika yang sama: cari kemiripan kalimatnya.</p></section>\n<section class=\"box catatan\"><h4>Inti teks (rangkuman bagian 2)</h4><p>Gudang PT Lintas Distribusi menguji alur kerja digital di satu zona. Ketiga indeks membaik, tetapi Maya menahan diri: keluhan pelanggan punya faktor lain, dan sebelum meluas perlu diuji di periode puncak, dicek kualitas datanya, serta dinilai beban kerja dan keselamatannya.</p></section>",
  "11": "<p class=\"keystatus ok\"><b>Jawaban: A</b> · Jenis soal: Inferensi • Makna Tindakan Tokoh</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>terutama menunjukkan</b> → kesimpulan sikap/watak tokoh</li><li><b>peta lama sebagai dasar</b> → peta jadi bahan, bukan perintah</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Daftar tindakan Lintang: membaca berita tanpa berpihak → membandingkan peta dengan kondisi kini → mengusulkan tanggul bersegmen.</li><li>Simpulkan: ia mengolah warisan menjadi pengetahuan untuk menimbang kepentingan dan risiko.</li><li>Coret opsi yang menyebut Lintang menolak, memihak satu kelompok, atau mengganti sains dengan kenangan.</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P2]</b> <i>“Lintang membaca berita itu tanpa segera berpihak.”</i><br><b>Maknanya:</b> Ia berpikir dulu sebelum bersikap.</p><p class=\"ev\"><b>[P3]</b> <i>“Mereka membandingkan peta lama dengan posisi rumah, kebun, dan saluran air saat ini.”</i><br><b>Maknanya:</b> Peta lama dipadukan dengan kondisi kini.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev ok\"><b>A. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Cocok dengan tindakan Lintang: peta dibandingkan dengan kondisi kini, lalu jadi dasar rancangan.</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Lintang sadar petanya mungkin tidak akurat dan tidak menolak rancangan pemerintah.</p>\n<p class=\"ev no\"><b>C. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Di forum warga ia tidak meminta rencana dibatalkan; ia menawarkan rancangan.</p>\n<p class=\"ev no\"><b>D. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Ia justru menggabungkan peta lama dengan pengamatan sekarang.</p>\n<p class=\"ev no\"><b>E. Salah</b> · <span class=\"trap\">Tidak ada di teks</span><br>Tidak ada petunjuk ia membela satu kelompok. Rancangannya melindungi permukiman sekaligus pedagang.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Tindakan = bukti watak. Tandai kata kerja tindakan tokoh (membaca, menyadari, membandingkan, mengusulkan, menawarkan), lalu simpulkan sikapnya dari rangkaian itu.</p></section>",
  "12": "<p class=\"keystatus ok\"><b>Jawaban: E</b> · Jenis soal: Evaluasi • Penyelesaian Konflik</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>pertentangan</b> → tarik-menarik tiga kepentingan</li><li><b>menyelesaikan</b> → jalan keluar yang ditempuh</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Lihat Peta Konflik di halaman pembuka bagian ini.</li><li>Cari opsi yang menjawab ketiganya: perlindungan, akses ekonomi, pengelolaan air.</li><li>Coret opsi yang memilih satu pihak saja atau menolak total.</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P3]</b> <i>“ia mengusulkan tanggul bersegmen dengan pintu air, jalur perahu yang tetap terbuka, serta taman resapan di lokasi bekas rawa.”</i><br><b>Maknanya:</b> Satu usulan, tiga kepentingan terjawab.</p><p class=\"ev\"><b>[P4]</b> <i>“Ia menunjukkan bagian yang berisiko dan menawarkan rancangan yang memungkinkan perlindungan permukiman tanpa memutus pekerjaan pedagang.”</i><br><b>Maknanya:</b> Perlindungan dan pekerjaan dijaga bersama.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev no\"><b>A. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Lintang tidak meminta rencana dibatalkan, ia memperbaikinya.</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Ia mengubah rancangan: jalur perahu dibuka dan tanggul dibuat bersegmen.</p>\n<p class=\"ev no\"><b>C. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Ia sendiri sadar petanya mungkin tidak akurat; tujuannya bukan membuktikan siapa yang lebih benar.</p>\n<p class=\"ev no\"><b>D. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Perlindungan permukiman tetap dijaga lewat tanggul bersegmen dan pintu air.</p>\n<p class=\"ev ok\"><b>E. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Ketiga kepentingan terjawab sekaligus, dan rancangan diuji bertahap pada satu segmen.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Siapkan tiga “kartu kepentingan” (permukiman, pedagang, lingkungan). Uji tiap opsi: berapa kartu yang terjawab? Jawaban benar menjawab ketiganya.</p></section>",
  "13": "<p class=\"keystatus ok\"><b>Jawaban: A · C · E</b> · Jenis soal: Pernyataan Sesuai • Peran Peta Lama · Pilih semua</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>peran peta lama</b> → fungsi peta dalam jalannya konflik</li><li><b>sesuai</b> → punya dasar di teks</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Daftar fungsi peta: menunjukkan bekas aliran lama, dibandingkan dengan kondisi kini, menjadi dasar usulan.</li><li>Cocokkan fungsi itu dengan tiap opsi.</li><li>Coret opsi yang mutlak: “seluruh rancangan pasti keliru” (B) dan “tanpa penyesuaian” (D).</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P2]</b> <i>“catatan tersebut memuat bekas aliran lama yang tidak tampak pada peta kota.”</i><br><b>Maknanya:</b> Dasar opsi A.</p><p class=\"ev\"><b>[P3]</b> <i>“Mereka membandingkan peta lama dengan posisi rumah, kebun, dan saluran air saat ini.”</i><br><b>Maknanya:</b> Dasar opsi C.</p><p class=\"ev\"><b>[P4]</b> <i>“Ia menunjukkan bagian yang berisiko dan menawarkan rancangan yang memungkinkan perlindungan permukiman tanpa memutus pekerjaan pedagang.”</i><br><b>Maknanya:</b> Dasar opsi E.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev ok\"><b>A. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Sesuai P2: catatan kakek memuat bekas aliran lama yang tidak tampak di peta kota.</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Lintang tidak meminta rencana dibatalkan, dan ia sadar petanya mungkin tidak akurat.</p>\n<p class=\"ev ok\"><b>C. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Sesuai P3: peta dibandingkan dengan posisi rumah, kebun, dan saluran air sekarang.</p>\n<p class=\"ev no\"><b>D. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Kakek menulis peta bukan perintah mengulang masa lalu; rancangan Lintang justru disesuaikan.</p>\n<p class=\"ev ok\"><b>E. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Sesuai P3 dan P4: usulan melindungi permukiman tanpa memutus pekerjaan pedagang.</p>\n<section class=\"box catatan warn\"><h4>Catatan</h4><p>Di soal aslinya tidak ada kalimat “pilih semua”, tetapi opsi A, C, dan E sama-sama sesuai teks (B dan D jelas salah). Karena itu di kuis ini ditambahkan kalimat “Pilih semua jawaban yang tepat.” Bila gurumu punya kunci resmi yang berbeda, ikuti kunci dari gurumu. Pola serupa ada pada soal 17 dan 20.</p></section>\n<section class=\"box tips\"><h4>Jurus</h4><p>Soal tanpa label “pilih semua” pun bisa punya lebih dari satu opsi benar. Periksa tiap opsi dengan tanda ✓ atau ✗, jangan berhenti di opsi pertama yang cocok.</p></section>",
  "14": "<p class=\"keystatus ok\"><b>Jawaban: C</b> · Jenis soal: Inferensial • Memaknai Warisan</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>inferensial</b> → disimpulkan dari bukti</li><li><b>memaknai warisan</b> → cara memandang peninggalan kakek</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Baca catatan kakek di P3: peta = cara membaca akibat.</li><li>Lihat tindakan Lintang: membandingkan, tidak menolak, menyusun usulan.</li><li>Simpulkan: warisan bernilai bila dipakai membaca risiko dan merancang solusi masa kini.</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P3]</b> <i>“Peta bukan perintah untuk mengulang masa lalu; peta adalah cara membaca akibat sebelum memilih arah.”</i><br><b>Maknanya:</b> Warisan dipakai untuk berpikir, bukan untuk diulang.</p><p class=\"ev\"><b>[P4]</b> <i>“nilai peta itu bukan terletak pada umurnya, melainkan pada pertanyaan yang masih dapat diajukan.”</i><br><b>Maknanya:</b> Nilai warisan ada pada kegunaannya kini.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev no\"><b>A. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Kakek menulis peta bukan perintah mengulang masa lalu.</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Lintang tetap memakai peta walau mungkin tidak sepenuhnya akurat, sebagai pembanding.</p>\n<p class=\"ev ok\"><b>C. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Selaras dengan catatan kakek dan tindakan Lintang.</p>\n<p class=\"ev no\"><b>D. Salah</b> · <span class=\"trap\">Tidak ada di teks</span><br>Tidak ada tuduhan itu; Lintang tidak menolak rancangan pemerintah.</p>\n<p class=\"ev no\"><b>E. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Lintang justru aktif menawarkan rancangan di forum warga.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Tulis kutipan catatan kakek lalu parafrasekan dengan kata sendiri. Inti catatan seperti ini hampir selalu menjadi dasar jawaban soal tema atau makna.</p></section>",
  "15": "<p class=\"keystatus ok\"><b>Jawaban: E</b> · Jenis soal: Evaluasi • Penyelesaian Konflik</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>pertentangan</b> → kenangan keluarga, perlindungan permukiman, pekerjaan warga</li><li><b>penyelesaian</b> → cara cerita mengakhiri konflik</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Ingat inti penyelesaian: peta lama diolah jadi rancangan yang diuji bertahap.</li><li>Cari opsi yang memuat tiga kepentingan terjawab.</li><li>Coret opsi yang mengorbankan salah satu kepentingan.</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P4]</b> <i>“Beberapa bulan kemudian, rancangan tersebut diuji pada satu segmen sungai sebelum diterapkan lebih luas.”</i><br><b>Maknanya:</b> Penyelesaian bertahap dan hati-hati.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev no\"><b>A. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Lintang tidak meminta rencana dibatalkan. “Mutlak” berlebihan.</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Ia memakai peta kakeknya dan mengubah rancangan.</p>\n<p class=\"ev no\"><b>C. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Kata “selalu” bertentangan dengan sikap Lintang yang menggabungkan keduanya.</p>\n<p class=\"ev no\"><b>D. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Rancangannya justru melindungi permukiman sekaligus membuka jalur perahu.</p>\n<p class=\"ev ok\"><b>E. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Cocok dengan P3 dan P4: rancangan diuji pada satu segmen dulu.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Bandingkan jawaban benar soal 12 dan 15: sama-sama “mengolah pengetahuan lama menjadi rancangan yang menggabungkan kepentingan”. Hanya kalimatnya yang berbeda.</p></section>\n<section class=\"box catatan\"><h4>Inti teks (rangkuman bagian 3)</h4><p>Lintang tidak langsung memihak saat kota merencanakan tanggul beton. Ia membandingkan peta lama kakeknya dengan kondisi sungai sekarang, lalu menawarkan rancangan yang melindungi permukiman, menjaga jalur perahu, dan mengelola air. Rancangan itu diuji dulu pada satu segmen.</p></section>",
  "16": "<p class=\"keystatus ok\"><b>Jawaban: C</b> · Jenis soal: Simpulan • Seluruh Teks</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>keseluruhan teks</b> → semua paragraf</li><li><b>simpulan yang paling tepat</b> → paling lengkap dan tidak berlebihan</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Baca P4: simpulan dan rekomendasi peneliti.</li><li>Rangkum: banyak faktor, dua metode dengan keterbatasan, kebijakan menyesuaikan tiap segmen.</li><li>Coret opsi yang memilih satu penyebab atau satu indikator.</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P4]</b> <i>“Berdasarkan keseluruhan bukti, peneliti menyimpulkan bahwa perubahan kualitas air dipengaruhi oleh gabungan faktor alamiah dan aktivitas manusia yang bekerja secara berbeda pada setiap segmen.”</i><br><b>Maknanya:</b> Simpulan resmi teks.</p><p class=\"ev\"><b>[P4]</b> <i>“Mereka merekomendasikan pemantauan terpadu dan kebijakan yang disesuaikan dengan karakter lokal, bukan satu tindakan seragam untuk seluruh sungai.”</i><br><b>Maknanya:</b> Rekomendasinya.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev no\"><b>A. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Teks tidak menetapkan penyebab tunggal, dan kebijakan disesuaikan karakter lokal.</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Kedua sumber data punya keterbatasan dan saling melengkapi.</p>\n<p class=\"ev ok\"><b>C. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Merangkum seluruh P3 dan P4.</p>\n<p class=\"ev no\"><b>D. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Teks tidak menyebut hujan sebagai penyebab tunggal. Kata “membuktikan” berlebihan.</p>\n<p class=\"ev no\"><b>E. Salah</b> · <span class=\"trap\">Detail kecil</span><br>Nitrat hanya tinggi di hilir dan polanya dipengaruhi debit. Itu satu detail, bukan inti.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Pada teks ilmiah, jawaban benar hampir selalu memakai bahasa berhati-hati (perlu, dapat, dipengaruhi). Curigai opsi bernada pasti: membuktikan, terutama, tunggal.</p></section>",
  "17": "<p class=\"keystatus ok\"><b>Jawaban: A · C · E</b> · Jenis soal: Implikasi • Penelitian &amp; Kebijakan · Pilih semua</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>implikasi</b> → langkah logis yang mengikuti temuan</li><li><b>cara penelitian dan kebijakan</b> → dua sisi yang harus dipenuhi</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Pisahkan dua sisi: (1) cara meneliti, (2) cara mengambil kebijakan.</li><li>Uji tiap opsi dengan bukti di P1, P3, dan P4.</li><li>Coret opsi yang menyebut “pasti keliru” dan “kebijakan seragam”.</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P1]</b> <i>“Oleh sebab itu, peneliti perlu membedakan antara hasil pengamatan, penafsiran, dan kesimpulan.”</i><br><b>Maknanya:</b> Dasar opsi A.</p><p class=\"ev\"><b>[P3]</b> <i>“alat otomatis dapat merekam perubahan harian dengan lebih teratur, sedangkan sampel lapangan memungkinkan analisis zat tertentu secara lebih rinci.”</i><br><b>Maknanya:</b> Dasar opsi C: dua jenis informasi.</p><p class=\"ev\"><b>[P4]</b> <i>“kebijakan yang disesuaikan dengan karakter lokal, bukan satu tindakan seragam untuk seluruh sungai.”</i><br><b>Maknanya:</b> Dasar opsi E.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev ok\"><b>A. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Sesuai P1.</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>P3: perbedaan hasil tidak boleh segera dianggap kesalahan salah satu metode.</p>\n<p class=\"ev ok\"><b>C. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>P3 menjelaskan dua jenis informasi berbeda, dan P4 merekomendasikan pemantauan terpadu.</p>\n<p class=\"ev no\"><b>D. Salah</b> · <span class=\"trap\">Kebalikan</span><br>P4: kebijakan disesuaikan karakter lokal, bukan satu tindakan seragam.</p>\n<p class=\"ev ok\"><b>E. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Sesuai P3 (tidak ada penyebab tunggal) dan P4 (kebijakan lokal).</p>\n<section class=\"box catatan warn\"><h4>Catatan</h4><p>Di soal aslinya kata perintahnya “paling tepat”, tetapi opsi A, C, dan E sama-sama sesuai teks (B dan D jelas salah). Karena itu di kuis ini ditambahkan kalimat “Pilih semua jawaban yang tepat.” Bila gurumu punya kunci resmi yang berbeda, ikuti kunci dari gurumu. Pola serupa ada pada soal 13 dan 20.</p></section>\n<section class=\"box tips\"><h4>Jurus</h4><p>Buat dua kolom: “Cara meneliti” dan “Cara mengambil kebijakan”. Tiap opsi benar masuk salah satunya, dan tidak ada yang mutlak.</p></section>",
  "18": "<p class=\"keystatus ok\"><b>Jawaban: D</b> · Jenis soal: Evaluasi • Simpulan &amp; Rekomendasi</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>proporsional</b> → sesuai takaran bukti</li><li><b>evaluasi</b> → menimbang kekuatan dan kelemahan</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Ingat tiga ciri simpulan peneliti: gabungan faktor, membandingkan keterbatasan metode, menyesuaikan kebijakan tiap segmen.</li><li>Cari opsi yang menyatakan simpulan itu layak karena tiga ciri tersebut.</li><li>Coret opsi yang menyebut simpulan lemah, atau yang menyuruh membuang satu metode.</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P3]</b> <i>“Peneliti tidak langsung menyatakan bahwa satu kegiatan tertentu merupakan penyebab tunggal perubahan kualitas air.”</i><br><b>Maknanya:</b> Kehati-hatian peneliti adalah kekuatan.</p><p class=\"ev\"><b>[P3]</b> <i>“Namun, kedua sumber data memiliki keterbatasan, sehingga perbedaan hasil tidak boleh segera dianggap sebagai kesalahan salah satu metode.”</i><br><b>Maknanya:</b> Kedua metode dipertahankan.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev no\"><b>A. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Justru kehati-hatian itu kekuatan; bukti menunjukkan banyak faktor.</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Alat otomatis merekam perubahan harian lebih teratur; sampel lapangan tidak menggantikannya.</p>\n<p class=\"ev no\"><b>C. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>P3 membantahnya: perbedaan hasil tidak boleh segera dianggap kesalahan.</p>\n<p class=\"ev ok\"><b>D. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Menilai dari tiga ciri simpulan peneliti.</p>\n<p class=\"ev no\"><b>E. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Pola di hilir pun dipengaruhi debit, dan rekomendasi teks justru kebijakan lokal.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Bedakan tegas dengan berlebihan. Simpulan ilmiah yang baik tegas pada hal yang didukung bukti, tetapi berhati-hati pada hal yang belum pasti.</p></section>",
  "19": "<p class=\"keystatus ok\"><b>Jawaban: A</b> · Jenis soal: Konsep • Tiga Lapis Berpikir Ilmiah</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>hasil pengamatan</b> → catatan, angka, deskripsi</li><li><b>penafsiran</b> → menghubungkan temuan dengan pola</li><li><b>kesimpulan</b> → dirumuskan hati-hati setelah bukti diperiksa</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Buka P1 dan beri label tiga lapis.</li><li>Cocokkan definisi tiap lapis dengan opsi.</li><li>Coret opsi yang menukar urutan atau menyamakan fungsi ketiganya.</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P1]</b> <i>“Hasil pengamatan berupa catatan, angka, atau deskripsi kondisi lapangan menjadi bahan awal.”</i><br><b>Maknanya:</b> Lapis 1.</p><p class=\"ev\"><b>[P1]</b> <i>“Penafsiran menghubungkan temuan-temuan tersebut dengan pola tertentu, sedangkan kesimpulan harus dirumuskan secara hati-hati setelah kekuatan bukti dan keterbatasan metode diperiksa.”</i><br><b>Maknanya:</b> Lapis 2 dan 3.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev ok\"><b>A. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Definisi persis seperti di P1.</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Semua dibalik: pengamatan adalah catatan/angka, dan kesimpulan datang setelah bukti diperiksa.</p>\n<p class=\"ev no\"><b>C. Salah</b> · <span class=\"trap\">Kebalikan</span><br>P1 membedakan ketiganya; kesimpulan tidak ditentukan satu jenis alat.</p>\n<p class=\"ev no\"><b>D. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Pengamatan adalah bahan awal, dan kesimpulan tidak harus satu penyebab tunggal.</p>\n<p class=\"ev no\"><b>E. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Peneliti harus membedakan ketiganya, dan perbedaan data tidak diabaikan (P3).</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Hafalkan urutannya: bahan masakan (pengamatan) → resep (penafsiran) → hidangan jadi (kesimpulan). Hidangan tidak disajikan sebelum dicicipi.</p></section>",
  "20": "<p class=\"keystatus ok\"><b>Jawaban: A · C · E</b> · Jenis soal: Implikasi Inferensial • Seluruh Penelitian · Pilih semua</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>implikasi inferensial</b> → akibat logis yang disimpulkan dari bukti</li><li><b>keseluruhan penelitian</b> → P1–P4</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Daftar temuan utama: pola beda antarsegmen, dua metode saling melengkapi, perbedaan hasil harus ditelaah.</li><li>Cocokkan tiap temuan dengan opsi.</li><li>Coret opsi yang menyebut penyebab tunggal (B) atau kebijakan seragam (D).</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P2]</b> <i>“Di segmen hilir, kadar nitrat memang lebih tinggi, tetapi perubahan debit akibat pembukaan pintu air membuat pola pencemarannya tidak sepenuhnya sama dengan segmen tengah.”</i><br><b>Maknanya:</b> Dasar opsi A.</p><p class=\"ev\"><b>[P3]</b> <i>“Namun, kedua sumber data memiliki keterbatasan, sehingga perbedaan hasil tidak boleh segera dianggap sebagai kesalahan salah satu metode.”</i><br><b>Maknanya:</b> Dasar opsi E (dan C).</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev ok\"><b>A. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Sesuai P2 dan P4.</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>P3 menolak penyebab tunggal, dan debit ikut memengaruhi pola nitrat.</p>\n<p class=\"ev ok\"><b>C. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>P3: alat otomatis merekam harian, sampel lapangan lebih rinci.</p>\n<p class=\"ev no\"><b>D. Salah</b> · <span class=\"trap\">Kebalikan</span><br>P4 merekomendasikan kebijakan sesuai karakter lokal.</p>\n<p class=\"ev ok\"><b>E. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Persis kalimat P3.</p>\n<section class=\"box catatan warn\"><h4>Catatan</h4><p>Di soal aslinya kata perintahnya “paling tepat”, tetapi opsi A, C, dan E sama-sama sesuai teks (B dan D jelas salah). Karena itu di kuis ini ditambahkan kalimat “Pilih semua jawaban yang tepat.” Bila gurumu punya kunci resmi yang berbeda, ikuti kunci dari gurumu. Pola serupa ada pada soal 13 dan 17.</p></section>\n<section class=\"box tips\"><h4>Jurus</h4><p>Strategi “tiga anak tangga”: A (temuan antarsegmen), C (alat ukur), E (cara menyikapi data). Opsi benar sering mewakili tiga sisi berbeda dari satu teks.</p></section>\n<section class=\"box catatan\"><h4>Inti teks (rangkuman bagian 4)</h4><p>Kualitas air Sungai Aruna diteliti di tiga segmen selama dua tahun. Peneliti tidak menyebut penyebab tunggal; mereka membandingkan data alat otomatis dengan sampel lapangan, lalu menyimpulkan bahwa kualitas air dipengaruhi gabungan faktor alamiah dan aktivitas manusia yang berbeda di tiap segmen.</p></section>",
  "21": "<p class=\"keystatus ok\"><b>Jawaban: B</b> · Jenis soal: Penilaian • Penerapan Sistem</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>penilaian paling tepat</b> → menimbang untung dan rugi</li><li><b>penerapan sistem</b> → hasil dan syarat pelaksanaannya</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Isi dua sisi neraca: manfaat awal dan masalah/syarat.</li><li>Cari opsi yang memuat keduanya.</li><li>Coret opsi “layak segera”, “hentikan”, atau “abaikan kekhawatiran pengemudi”.</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P2]</b> <i>“Namun, hasil tersebut tidak berarti sistem selalu memberikan diagnosis yang tepat.”</i><br><b>Maknanya:</b> Manfaat ada, tetapi ketepatan belum terjamin.</p><p class=\"ev\"><b>[P3]</b> <i>“Karena itu, pimpinan mempertimbangkan perluasan sistem hanya setelah uji silang dengan pemeriksaan mekanik, aturan penggunaan data, dan ukuran keberhasilan disepakati.”</i><br><b>Maknanya:</b> Perluasan bersyarat.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev no\"><b>A. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>P2 menyebut peringatan keliru dan kegagalan mendeteksi. Kata “selalu” berlebihan.</p>\n<p class=\"ev ok\"><b>B. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Seimbang dan memuat semua syarat di P3.</p>\n<p class=\"ev no\"><b>C. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Manfaat awal nyata (18 jam → 11 jam). “Membuktikan tidak sesuai” berlebihan.</p>\n<p class=\"ev no\"><b>D. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Teks menyebut kekhawatiran pengemudi dan ukuran keberhasilan yang harus disepakati.</p>\n<p class=\"ev no\"><b>E. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Pimpinan justru mensyaratkan aturan data dan uji silang.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Pola “Ya, tetapi”: evaluasi terbaik mengakui manfaat lalu menyebut syarat. Opsi tanpa kata “tetapi” (atau padanannya) biasanya hanya memuji atau hanya mencela.</p></section>",
  "22": "<p class=\"keystatus ok\"><b>Jawaban: A</b> · Jenis soal: Cara Kerja &amp; Batas Penggunaan</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>cara kerja</b> → apa yang dikerjakan sistem</li><li><b>batas penggunaannya</b> → apa yang belum bisa diandalkan</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Cari cara kerja di P1: sensor + riwayat perbaikan → dasbor → penjadwalan.</li><li>Cari batas di P2–P3: peringatan keliru, gagal mendeteksi, perlu verifikasi.</li><li>Pilih opsi yang memuat dua hal itu bersamaan.</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P1]</b> <i>“Sistem baru memanfaatkan sensor suhu mesin, getaran, tekanan ban, dan riwayat perbaikan.”</i><br><b>Maknanya:</b> Cara kerja.</p><p class=\"ev\"><b>[P3]</b> <i>“serta aturan yang membedakan pemeriksaan wajib dari peringatan yang masih memerlukan verifikasi”</i><br><b>Maknanya:</b> Batas: peringatan masih perlu diverifikasi.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev ok\"><b>A. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Memuat cara kerja (P1) dan batas (P2–P3).</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Teks menyebut peringatan keliru, jadi mekanik tetap diperlukan.</p>\n<p class=\"ev no\"><b>C. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Sensor memantau suhu mesin, getaran, dan tekanan ban. Jaringan dan kalibrasi justru memengaruhi ketepatan data.</p>\n<p class=\"ev no\"><b>D. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Teks tidak menyebut syarat sempurna seperti itu; sistem sudah dipakai dan terus disempurnakan.</p>\n<p class=\"ev no\"><b>E. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Tidak semua kerusakan terdeteksi (contoh: ban). Kata “semua” dan “membuktikan” berlebihan.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Soal “cara kerja + batas” selalu punya dua bagian. Periksa opsi bagian demi bagian: apakah bagian pertama benar, apakah bagian kedua benar?</p></section>",
  "23": "<p class=\"keystatus ok\"><b>Jawaban: E</b> · Jenis soal: Sebab • Alasan Pimpinan</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>alasan paling kuat</b> → alasan dengan bukti paling langsung di teks</li><li><b>belum segera memperluas</b> → syarat belum terpenuhi</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Lihat kalimat keputusan pimpinan di akhir P3: perluasan hanya setelah tiga hal disepakati.</li><li>Tiga hal itu adalah alasannya: uji silang/ketepatan, aturan penggunaan data, ukuran keberhasilan.</li><li>Cari opsi yang memuat alasan itu. Coret alasan yang tidak pernah disebut (biaya, kondisi jalan, penolakan formulir).</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P3]</b> <i>“Manajemen belum menjelaskan batas akses terhadap data perjalanan maupun prosedur koreksi jika catatan sistem dianggap keliru.”</i><br><b>Maknanya:</b> Aturan data belum jelas.</p><p class=\"ev\"><b>[P3]</b> <i>“Karena itu, pimpinan mempertimbangkan perluasan sistem hanya setelah uji silang dengan pemeriksaan mekanik, aturan penggunaan data, dan ukuran keberhasilan disepakati.”</i><br><b>Maknanya:</b> Syarat perluasan.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev no\"><b>A. Salah</b> · <span class=\"trap\">Tidak ada di teks</span><br>Biaya tidak pernah dibahas di teks.</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Mekanik memeriksa peringatan sensor dan menduga sebab ketidaktepatannya, jadi data sensor sudah dipakai.</p>\n<p class=\"ev no\"><b>C. Salah</b> · <span class=\"trap\">Tidak ada di teks</span><br>Teks tidak membatasi manfaat pada jalan baik. Muatan dan rute disebut dalam kekhawatiran penilaian kinerja.</p>\n<p class=\"ev no\"><b>D. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Pengemudi diminta melapor lewat formulir dan khawatir soal penggunaan data, bukan menolak formulir.</p>\n<p class=\"ev ok\"><b>E. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Sesuai syarat pimpinan di akhir P3.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Untuk soal “alasan paling kuat”, tanyakan, “Di kalimat mana teks menyebut alasan ini?” Alasan yang bagus bisa ditunjuk, bukan dikarang.</p></section>",
  "24": "<p class=\"keystatus ok\"><b>Jawaban: A · C · E</b> · Jenis soal: Dasar Evaluasi · Pilih semua</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>dasar evaluasi</b> → pijakan menilai sebelum meluas</li><li><b>pilih semua</b> → periksa tiap opsi</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Gunakan neraca: manfaat awal di kiri, masalah/syarat di kanan.</li><li>Uji tiap opsi: apakah mengakui manfaat dan/atau menuntut syarat?</li><li>Coret opsi yang menyatakan “sudah pasti berhasil” (B) atau “kekhawatiran dikesampingkan” (D).</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P3]</b> <i>“Tim itu mengusulkan kalibrasi berkala, pencatatan tindakan setelah setiap peringatan, serta aturan yang membedakan pemeriksaan wajib dari peringatan yang masih memerlukan verifikasi.”</i><br><b>Maknanya:</b> Dasar opsi C.</p><p class=\"ev\"><b>[P3]</b> <i>“Akan tetapi, sebagian pengemudi khawatir data tersebut digunakan untuk menilai kinerja mereka tanpa mempertimbangkan beban muatan, kondisi rute, dan keputusan mekanik.”</i><br><b>Maknanya:</b> Dasar opsi E.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev ok\"><b>A. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Sesuai P2: 18 jam → 11 jam.</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>“Sudah dapat dipastikan” berlebihan; masalah ketepatan masih nyata.</p>\n<p class=\"ev ok\"><b>C. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Persis usulan tim evaluasi di P3.</p>\n<p class=\"ev no\"><b>D. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Pengemudi khawatir justru data dipakai menilai kinerja; manajemen belum menjelaskan batas aksesnya.</p>\n<p class=\"ev ok\"><b>E. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Sesuai P3: akses, koreksi, dan ukuran keberhasilan.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Baca kata “dasar”: dasar evaluasi = hal yang perlu dipenuhi sebelum menyimpulkan. Opsi yang sudah menyimpulkan (“sudah pasti berhasil”) tidak cocok.</p></section>",
  "25": "<p class=\"keystatus ok\"><b>Jawaban: B</b> · Jenis soal: Hasil Awal &amp; Batas Penerapan</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>hasil awal</b> → manfaat yang sudah terlihat</li><li><b>batas penerapan</b> → syarat sebelum meluas</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Tulis dua hal: manfaat awal (waktu berhenti turun, suku cadang darurat berkurang) dan batas (kalibrasi, verifikasi, aturan data).</li><li>Cari opsi yang memuat keduanya.</li><li>Coret opsi yang hanya memuji, hanya mencela, atau mengabaikan peran pengemudi.</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P2]</b> <i>“Penggunaan suku cadang darurat juga berkurang.”</i><br><b>Maknanya:</b> Manfaat awal kedua.</p><p class=\"ev\"><b>[P3]</b> <i>“Manajemen belum menjelaskan batas akses terhadap data perjalanan maupun prosedur koreksi jika catatan sistem dianggap keliru.”</i><br><b>Maknanya:</b> Batas penerapan.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev no\"><b>A. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>“Membuktikan” dan “selalu” berlebihan, dan bertentangan dengan adanya peringatan keliru.</p>\n<p class=\"ev ok\"><b>B. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Memuat manfaat dan batas sekaligus.</p>\n<p class=\"ev no\"><b>C. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Manfaat awal nyata. Masalah ketepatan tidak meniadakan manfaat.</p>\n<p class=\"ev no\"><b>D. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Pengemudi dilibatkan lewat formulir, dan aturan akses data termasuk syarat perluasan.</p>\n<p class=\"ev no\"><b>E. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Ketepatan peringatan justru memengaruhi keputusan perawatan, dan teks mensyaratkan ukuran keberhasilan yang disepakati.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Bandingkan jawaban benar soal 21 (B) dan soal 25 (B): keduanya memuat “manfaat awal + perlu disempurnakan”. Cari pola yang sama pada soal 22.</p></section>\n<section class=\"box catatan\"><h4>Inti teks (rangkuman bagian 5)</h4><p>Sebuah bengkel kendaraan niaga memakai sensor untuk memprediksi kerusakan. Hasil awalnya baik (waktu berhenti turun dari 18 jam menjadi 11 jam), tetapi ada peringatan keliru, satu kegagalan deteksi, dan kekhawatiran pengemudi soal data. Pimpinan memperluas sistem hanya setelah syaratnya disepakati.</p></section>",
  "26": "<p class=\"keystatus ok\"><b>Jawaban: D</b> · Jenis soal: Simpulan Inferensial • Perubahan Pemahaman</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>simpulan inferensial</b> → disimpulkan dari bukti</li><li><b>perubahan pemahaman</b> → dari tidak tahu</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Bandingkan awal dan akhir: awalnya hanya “Kakek pergi dan tidak kembali”, akhirnya tahu soal ancaman dan surat yang tak sampai.</li><li>Lihat sikap akhir Lintang: tidak memaafkan, tidak menyalahkan, menunda, mencari kesaksian.</li><li>Coret opsi yang memakai kata “memastikan”, “pasti”, “sepenuhnya”.</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P4]</b> <i>“Kakek tidak sekadar meninggalkan keluarga; ia bersembunyi setelah seorang warga dipanggil aparat karena menyebarkan dokumentasi tersebut.”</i><br><b>Maknanya:</b> Kepergian Kakek terkait ancaman.</p><p class=\"ev\"><b>[P4]</b> <i>“Lintang tidak langsung memaafkan maupun menyalahkan siapa pun.”</i><br><b>Maknanya:</b> Sikap berhati-hati.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev no\"><b>A. Salah</b> · <span class=\"trap\">Tidak ada di teks</span><br>Tidak ada petunjuk pekerjaan di kota; Kakek bersembunyi karena ancaman.</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Nenek menyimpan surat karena takut keselamatan keluarga terancam.</p>\n<p class=\"ev no\"><b>C. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Lintang justru menunda pengosongan rumah dan tidak menyerahkan foto.</p>\n<p class=\"ev ok\"><b>D. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Sesuai P3–P4 dan sikap akhir Lintang.</p>\n<p class=\"ev no\"><b>E. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Lintang tidak menyalahkan siapa pun. Kata “memastikan”, “sepenuhnya”, “satu-satunya” berlebihan.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Pakai tabel “Sudah pasti vs belum pasti” di halaman pembuka. Semua opsi salah memuat hal yang belum boleh dipastikan.</p></section>",
  "27": "<p class=\"keystatus ok\"><b>Jawaban: A · B · D</b> · Jenis soal: Penilaian Penyelesaian · Pilih semua</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>membangun penyelesaian</b> → cara cerita mengakhiri konflik</li><li><b>penyelesaian terbuka</b> → konflik belum dituntaskan</li><li><b>pilih semua</b> → periksa tiap opsi</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Tentukan sifat penyelesaian: terbuka, bukan tuntas.</li><li>Uji tiap opsi dengan fakta: apa yang dilakukan Lintang, apa fungsi kamera dan foto, apa hasil pengakuan Nenek.</li><li>Coret opsi yang menyebut konflik “tuntas” (C) atau Lintang ingin menyerahkan foto ke mandor (E).</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P4]</b> <i>“Ia menunda pengosongan rumah, lalu mengajak Nenek mencari warga yang masih mengingat peristiwa tersebut.”</i><br><b>Maknanya:</b> Penyelesaian bertahap, mencari kesaksian.</p><p class=\"ev\"><b>[P3]</b> <i>“Hasilnya memperlihatkan rumah-rumah warga yang retak, saluran air tertutup material, dan seorang petugas proyek yang sedang memeriksa peta.”</i><br><b>Maknanya:</b> Foto sebagai bukti sosial.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev ok\"><b>A. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Sesuai P1 (tugas praktis) dan P4 (menunda, mencari warga).</p>\n<p class=\"ev ok\"><b>B. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Foto memuat dokumentasi rumah retak dan proyek, dan mengungkap sebab kepergian Kakek.</p>\n<p class=\"ev no\"><b>C. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Lintang tidak langsung memaafkan atau menyalahkan; konflik belum tuntas.</p>\n<p class=\"ev ok\"><b>D. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Persis tindakan Lintang di akhir cerita.</p>\n<p class=\"ev no\"><b>E. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Lintang menunda pengosongan. Tujuannya memahami, bukan mempercepat pembongkaran.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Penyelesaian terbuka = pertanyaan akhir cerita tidak dijawab tuntas, tetapi arah sikap tokoh jelas. Tunjuk kalimat yang menunjukkan konflik belum selesai.</p></section>",
  "28": "<p class=\"keystatus ok\"><b>Jawaban: C</b> · Jenis soal: Urutan Peristiwa</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>urutan peristiwa</b> → urutan kejadian berdasar waktu</li><li><b>setelah menemukan kamera film tua</b> → mulai dari P2</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Buat garis waktu (lihat di bawah).</li><li>Cek tiap opsi dari kejadian pertama: film dicuci dulu atau foto diperlihatkan dulu?</li><li>Coret opsi yang mengubah urutan atau menambahkan kejadian yang tidak ada (menyerahkan kamera, membatalkan pembongkaran).</li></ol></section>\n<section class=\"box cepat\"><h4>Garis waktu tindakan Lintang</h4><ol class=\"steps\"><li>Menemukan kamera film tua</li><li>Membawa film ke kios pencuci foto</li><li>Melihat hasil foto dan catatan Kakek</li><li>Menunjukkan foto kepada Nenek</li><li>Menunda pengosongan, mengajak Nenek mencari warga</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P3]</b> <i>“Lintang membawa gulungan film itu ke kios pencuci foto di pasar.”</i><br><b>Maknanya:</b> Kejadian setelah menemukan kamera.</p><p class=\"ev\"><b>[P4]</b> <i>“Ia menunda pengosongan rumah, lalu mengajak Nenek mencari warga yang masih mengingat peristiwa tersebut.”</i><br><b>Maknanya:</b> Kejadian terakhir.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev no\"><b>A. Salah</b> · <span class=\"trap\">Tidak ada di teks</span><br>Tidak ada penyerahan kamera, dan pembongkaran tidak dibatalkan, hanya pengosongan ditunda.</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Urutan terbalik: film dicuci dulu, baru foto bisa ditunjukkan.</p>\n<p class=\"ev ok\"><b>C. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Cocok dengan garis waktu P3–P4.</p>\n<p class=\"ev no\"><b>D. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Penundaan terjadi di akhir. Nenek menjelaskan setelah melihat foto, bukan karena diminta.</p>\n<p class=\"ev no\"><b>E. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Kamera ditemukan lebih dulu, dan kunci tidak diserahkan setelah membaca surat.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Beri nomor 1–5 pada kejadian di samping teks, lalu coret opsi yang urutannya meloncat. Kata “terlebih dahulu” dan “lalu” adalah petunjuk urutan.</p></section>",
  "29": "<p class=\"keystatus ok\"><b>Jawaban: D</b> · Jenis soal: Simpulan Inferensial • Perubahan Sikap</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>perubahan sikap</b> → dari tidak tahu</li><li><b>keputusan pada akhir cerita</b> → menunda dan mencari warga</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Ingat tabel “sudah pasti vs belum pasti”.</li><li>Cari opsi yang menyebut ancaman, ketakutan, informasi tidak tersampaikan, dan sikap tidak menghakimi.</li><li>Coret opsi yang memakai kata memastikan atau menyimpulkan sesuatu yang tidak ada di teks.</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P3]</b> <i>“Catatan lain, yang ditulis tergesa-gesa, meminta Nenek menyimpan salinan foto sampai keadaan lebih aman.”</i><br><b>Maknanya:</b> Tanda adanya ketakutan.</p><p class=\"ev\"><b>[P4]</b> <i>“Nenek menyimpan surat itu karena takut keselamatan keluarga ikut terancam.”</i><br><b>Maknanya:</b> Alasan kebisuan Nenek.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev no\"><b>A. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Catatan Kakek justru ingin memastikan tidak ada keluarga yang terancam. Menyimpulkan seperti itu terlalu cepat.</p>\n<p class=\"ev no\"><b>B. Salah</b> · <span class=\"trap\">Kebalikan</span><br>Nenek menyimpan surat karena takut, bukan memalsukan kisah.</p>\n<p class=\"ev no\"><b>C. Salah</b> · <span class=\"trap\">Tidak ada di teks</span><br>Tidak ada rencana menuntut; ia mengajak Nenek mencari warga yang ingat.</p>\n<p class=\"ev ok\"><b>D. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Sesuai P3–P4.</p>\n<p class=\"ev no\"><b>E. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Tidak ada kepastian seperti itu; penyelesaian masih terbuka.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Bandingkan jawaban benar soal 26 dan 29. Kalimatnya hampir sama: dua soal bisa menguji satu pemahaman yang sama.</p></section>",
  "30": "<p class=\"keystatus ok\"><b>Jawaban: A · B · D</b> · Jenis soal: Penilaian Penyelesaian · Pilih semua</p>\n<section class=\"box rumus\"><h4>Kata kunci</h4><ul><li><b>perkembangan batin</b> → perubahan pikiran dan perasaan tokoh</li><li><b>fungsi kamera dan foto</b> → alat membuka masa lalu</li><li><b>pilih semua</b> → periksa tiap opsi</li></ul></section>\n<section class=\"box cepat\"><h4>Langkah menjawab</h4><ol class=\"steps\"><li>Ingat sifat penyelesaian: terbuka, bertahap, dan hati-hati.</li><li>Uji tiap opsi dengan fakta di P3–P4.</li><li>Coret opsi yang menyebut Nenek “sepenuhnya bersalah” (C) atau konflik “tuntas” (E).</li></ol></section>\n<section class=\"box awam\"><h4>Bukti di teks</h4><p class=\"ev\"><b>[P3]</b> <i>“Hasilnya memperlihatkan rumah-rumah warga yang retak, saluran air tertutup material, dan seorang petugas proyek yang sedang memeriksa peta.”</i><br><b>Maknanya:</b> Foto menghubungkan luka keluarga dengan persoalan warga.</p><p class=\"ev\"><b>[P4]</b> <i>“Lintang tidak langsung memaafkan maupun menyalahkan siapa pun.”</i><br><b>Maknanya:</b> Penyelesaian terbuka.</p></section>\n<h4 class=\"steps-title\">Bedah setiap pilihan jawaban</h4>\n<p class=\"ev ok\"><b>A. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Dari kamera → foto → catatan → pengakuan Nenek.</p>\n<p class=\"ev ok\"><b>B. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Persis tindakan akhir di P4.</p>\n<p class=\"ev no\"><b>C. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Nenek menyimpan surat karena takut keselamatan keluarga terancam. “Sepenuhnya bersalah” tidak didukung.</p>\n<p class=\"ev ok\"><b>D. Benar</b> · <span class=\"trap trap-key\">Kunci jawaban</span><br>Foto memuat rumah retak, saluran air, dan petugas proyek. Teks tidak menyalahkan satu pihak.</p>\n<p class=\"ev no\"><b>E. Salah</b> · <span class=\"trap\">Terlalu ekstrem</span><br>Lintang tidak langsung memaafkan maupun menyalahkan siapa pun.</p>\n<section class=\"box tips\"><h4>Jurus</h4><p>Soal 27 dan 30 sama-sama “pilih semua” dengan jawaban A, B, D. Cari tiga sisi yang selalu muncul: fungsi benda, sikap tokoh, dan sifat penyelesaian terbuka.</p></section>\n<section class=\"box catatan\"><h4>Inti teks (rangkuman bagian 6)</h4><p>Saat memilah barang di rumah kaca kakeknya, Lintang menemukan kamera film tua. Hasil cuci filmnya dan pengakuan Nenek membuka alasan Kakek pergi: ancaman dan ketakutan. Lintang tidak langsung menyalahkan atau memaafkan siapa pun; ia menunda pengosongan rumah dan mencari kesaksian warga (penyelesaian terbuka).</p></section>"
};
